$ErrorActionPreference='Stop'
$root=Split-Path $PSScriptRoot -Parent;$e=Join-Path $root 'docs/evidence';$runner=Get-Content (Join-Path $e 'launch-regression-runner.txt')
$groups=@(
 @{name='Ledger, transport and filtered metadata batch';expected=55;exe='Tests'},
 @{name='Save conflicts, backups, preferences and OAuth';expected=55;exe='VaultTests'},
 @{name='Streaming, devices and launch-during-staging safety';expected=16;exe='StreamingTests'},
 @{name='Passcode persistence and throttling';expected=9;exe='SecurityTests'},
 @{name='Application protection';expected=15;exe='ApplicationLockTests'},
 @{name='Add-on peers, conflicts and rollback';expected=18;exe='SetupTests'},
 @{name='GameActivity identity and duplicate protection';expected=18;exe='ActivityTests'},
 @{name='HLTB progress and identity checks';expected=11;exe='HltbTests'},
 @{name='Pinned runtime integrity';expected=4;exe='RuntimeTests'}
)
foreach($g in $groups){$file=Join-Path $runner ($g.exe+'.txt');if((Get-Content $file -Raw)-notmatch ('RESULT '+$g.expected+' passed, 0 failed')){throw ('Missing passing group '+$g.name)};Copy-Item $file (Join-Path $e ('launch-'+$g.exe+'.txt')) -Force;$g.passed=$g.expected;$g.failed=0}
$runs=@();foreach($prefix in @('launch-final-local','launch-final-cloud')){foreach($peer in @('A','B','Verify')){$file=$prefix+'-'+$peer+'.json';$v=Get-Content (Join-Path $e $file) -Raw|ConvertFrom-Json;if(!$v.passed-or $v.launchMilliseconds -ge 10000-or $v.metadataMilliseconds -ge 10000){throw ('Timing or convergence failure: '+$file)};$runs+=@{run=$prefix+'-'+$peer;launchMs=$v.launchMilliseconds;metadataMs=$v.metadataMilliseconds;sessions=$v.gameActivitySessions;seconds=$v.playtime;passed=$true;evidence=$file}}}
$old=Join-Path $root 'docs/ACCEPTANCE-0.5.md';if(!(Test-Path $old)){Copy-Item (Join-Path $root 'docs/ACCEPTANCE.md') $old}
@{version='0.5.1';unitPassed=201;unitFailed=0;groups=$groups;launchRuns=$runs;targetMilliseconds=10000;allPassed=$true;priorAcceptance='ACCEPTANCE-0.5.md'}|ConvertTo-Json -Depth 10|Set-Content (Join-Path $e 'acceptance-tally.json')
$lines=@('# Acceptance report — Playnite Link 0.5.1','','The previous 45-second launch path queued a full-vault network synchronization behind existing work. Ordinary launches now proceed from local saves without waiting for network work. Known cached conflicts, unfinished sessions, app protection and the final local save replacement remain safeguards. Cloud saves discovered during play are deferred until the game stops. Users switching devices can explicitly synchronize first when they need the newest remote save before starting.','','Device, ledger, GameActivity and save-revision metadata use one filtered Rclone download. Blob payloads and unrelated folders are excluded. Game data converges before optional HLTB/add-on work. The GameActivity retry waits for the current cycle and avoids an unconditional second full synchronization.','','## Actual two-device timing','','Real Playnite 10.62 Desktop and Fullscreen instances, with GameActivity 3.7 and HowLongToBeat 3.13 enabled. The Google Drive run uses the existing authorized personal Rclone connection under a unique synthetic prefix. Launch occurs while background sync is already in progress. Each peer performs five repeated syncs; the first peer is restarted and verifies convergence without gameplay events.','','| Run | Launch ms | Warm metadata ms | Sessions | Seconds |','|---|---:|---:|---:|---:|')
foreach($r in $runs){$lines+='| '+$r.run+' | '+$r.launchMs+' | '+$r.metadataMs+' | '+$r.sessions+' | '+$r.seconds+' |'}
$lines+=@('','All measured launches and warm metadata checks are below the 10,000 ms target. A zero launch value on Verify means no game was launched during that phase. Cloud checks are real WAN measurements; local-alias results are labeled separately. These timings do not promise that arbitrary large save transfers, offline networks, quota failures, user conflict decisions or addon installations finish in ten seconds.','','## Automated regression checks','','| Group | Passed | Failed |','|---|---:|---:|')
foreach($g in $groups){$lines+='| '+$g.name+' | '+$g.passed+' | 0 |'}
$lines+=@('','**201 checks passed.** Save staging is tested with a launch-time veto after remote files have staged: local contents remain unchanged, no backup/swap occurs, and the temporary stage is cleaned up. The actual Desktop and Fullscreen save host tests cover cloud/local conflict choices, canceled launches, backups, preferences, stable UI navigation and no global progress dialogs.','','The 0.5 session/online HLTB acceptance is retained in [the prior report](ACCEPTANCE-0.5.md). This change does not alter online HLTB progress semantics. Physical ROG Ally hardware is not claimed; the two actual Windows profiles exercise Desktop/Fullscreen modes. Save directories, addon sharing and online HLTB remain explicit local configuration choices.')
$lines|Set-Content (Join-Path $root 'docs/ACCEPTANCE.md');Write-Output 'Verified 201 checks and six launch/convergence phases.'
